/* Neutron reactions per target "Z_N". Probabilities per nuclear encounter at thermal (≤0.5 eV) and
   fast (≥100 keV) energies, from the ratios of measured cross-sections (σ_capture, σ_fission, σ_scatter). */
/* Binding energies of the heavy nuclides in the decay table, derived from its measured Q-values: each decay links
   a parent's binding energy to its daughter's, so walking every chain up from the stable lead and bismuth it ends
   in gives the Atomic Mass Evaluation's values (²³⁸U: 1801.7 MeV, 7.570 MeV per nucleon) instead of the
   semi-empirical formula's, which overbinds the actinides by about 13 MeV. */
(() => {
  Object.assign(BINDING, { '82_124': 1622.324, '82_125': 1629.062, '82_126': 1636.430, '83_126': 1640.230 }); // AME2020
  const MNP = 0.782347; // (m_n − m_p − m_e)c², MeV
  const step = { a: [-2, -2], 'b-': [1, -1], 'b+': [-1, 1], ec: [-1, 1], p: [-1, 0], n: [0, -1] };
  for (let pass = 0; pass < 40; pass++) {
    let added = 0;
    for (const [key, d] of Object.entries(DECAY)) {
      if (BINDING[key] !== undefined) continue;
      const [Z, N] = key.split('_').map(Number);
      const modes = Array.isArray(d[1]) ? d[1] : [[d[1], 1, d[2]]];
      for (const [m, , Q] of modes) {
        const s = step[m];
        if (!s || !(Q > 0)) continue;
        const bd = BINDING[(Z + s[0]) + '_' + (N + s[1])];
        if (bd === undefined) continue;
        // Q from atomic masses: α: B(d) + B(⁴He) − B(p); β⁻: B(d) − B(p) + (mₙ − mₚ − mₑ); β⁺ and EC (the table lists
        // Q_EC): B(d) − B(p) − (mₙ − mₚ − mₑ); nucleon emission: B(d) − B(p)
        BINDING[key] = m === 'a' ? bd + BINDING['2_2'] - Q : m === 'b-' ? bd + MNP - Q : m === 'b+' || m === 'ec' ? bd - MNP - Q : bd - Q;
        added++;
        break;
      }
    }
    if (!added) break;
  }
})();

