  const mixer = new Broyden(nsh, maxIter, MIX_DAMP);
  let iscf = 0, converged = false, eelec = 0, eext = 0, emo = null, focc = null;
  const vsh = new Float64Array(nsh), vao = new Float64Array(nao);
