      const Cf = Ct;                                                 // Cf_mk = C_mk f_k (0 for the orbitals left out)
      for (let m = 0; m < nao; m++) for (let k = 0; k < nk; k++) Cf[m * nao + k] = focc[k] > 1e-15 ? C[m * nao + k] * focc[k] : 0;
