    const A = mbAtom(b.a), B = mbAtom(b.b); if (!A || !B) continue;
    const [ax, ay] = mbScr(A.x, A.y), [bx, by] = mbScr(B.x, B.y), dx = bx - ax, dy = by - ay, L2 = dx * dx + dy * dy || 1;
