  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const a of MB.atoms) {
    const m = mbImplicitH(a) ? 1.2 : 0.5;
    x0 = Math.min(x0, a.x - m); x1 = Math.max(x1, a.x + m); y0 = Math.min(y0, a.y - m); y1 = Math.max(y1, a.y + m);
  }
