{"type":"molecule","name":"…","smiles":"…","cat":"…","note":"…"}
{"type":"peptide","name":"…","sequence":"…","cat":"bio","note":"…"}
{"type":"lattice","name":"…","lattice":"ionic|metal|honeycomb|square","elements":["…"],"size":8,"cat":"…","note":"…"}
{"type":"object","key":"…","note":"…"}
{"type":"none","note":"…"}

