  $('galClose').onclick = () => hideModal('galModal');
  $('galSave').onclick = () => galSave();
  $('galName').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); galSave(); } e.stopPropagation(); });
