  let want = cap.findIndex(c => c >= need * 1.05);
  if (want < 0) { const mx = Math.max(...cap); want = mx >= 1.2 * cap[0] ? cap.findIndex(c => c >= cap[0] + 0.8 * (mx - cap[0])) : 0; }
